import { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router";
import { Button } from "@/presentation/components/ui/button";
import { Card } from "@/presentation/components/ui/card";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogFooter,
	DialogHeader,
	DialogTitle,
} from "@/presentation/components/ui/dialog";
import { Progress } from "@/presentation/components/ui/progress";
import { resolveLessonContent } from "../../domain/script/data/lessonContent";
import { lessonEntryByNumber } from "../../domain/script/data/lessonSequence";
import type { PropertyCard } from "../../domain/shared/types";
import { SectionHeader } from "../components/atoms/SectionHeader";
import { SessionStatGrid } from "../components/molecules/SessionStatGrid";
import { AchievementBadge } from "../components/organisms/AchievementBadge";
import { LessonIntro } from "../components/organisms/LessonIntro";
import { MultipleChoice } from "../components/organisms/MultipleChoice";
import { useApp } from "../hooks/useApp";
import { useSessionFlow } from "../hooks/useSessionFlow";

type Phase = "intro" | "quiz" | "complete";

export function LessonPage() {
	const { lessonNumber } = useParams<{ lessonNumber: string }>();
	const num = Number(lessonNumber);
	const navigate = useNavigate();
	const { lesson, refresh, checkAchievements } = useApp();

	const [phase, setPhase] = useState<Phase>("intro");
	const [cards, setCards] = useState<PropertyCard[]>([]);
	const [blockedMessage, setBlockedMessage] = useState<string | null>(null);
	const flow = useSessionFlow(cards.length);

	const achievementsCheckedRef = useRef(false);
	const [newAchievements, setNewAchievements] = useState<string[]>([]);

	const summary = useMemo(() => {
		try {
			return lesson.getScriptSummary(num);
		} catch {
			return null;
		}
	}, [lesson, num]);

	// What this lesson serves — video or deck. Resolved from the declared
	// sequence, independently of `summary`: a lesson can be declared in the
	// sequence and still fail to resolve content (an "unresolvable" lesson
	// must never read the same as one that doesn't exist at all).
	const contentResolution = useMemo(() => {
		const entry = lessonEntryByNumber(num);
		if (!entry) return { status: "undeclared" as const };
		return resolveLessonContent(entry.id);
	}, [num]);

	useEffect(() => {
		if (flow.isComplete) {
			lesson.completeScript(num);
			refresh();
			setPhase("complete");
		}
	}, [flow.isComplete, lesson, num, refresh]);

	useEffect(() => {
		if (phase === "complete" && !achievementsCheckedRef.current) {
			achievementsCheckedRef.current = true;
			const sessionSummary = {
				sessionId: `lesson-${num}-${Date.now()}`,
				completedAt: new Date().toISOString(),
				type: "lesson" as const,
				durationMs: 0,
				totalCards: flow.correct + flow.incorrect,
				correctCount: flow.correct,
				incorrectCount: flow.incorrect,
				accuracy: flow.accuracy.percentage,
				newCardsGraduated: 0,
			};
			const ids = checkAchievements(sessionSummary);
			setNewAchievements(ids);
		}
	}, [
		phase,
		num,
		flow.correct,
		flow.incorrect,
		flow.accuracy.percentage,
		checkAchievements,
	]);

	if (!summary) {
		return (
			<div className="text-center py-8">
				<p style={{ color: "var(--color-text-muted)" }}>Lesson not found</p>
				<Button variant="link" className="mt-4" onClick={() => navigate("/")}>
					Go Home
				</Button>
			</div>
		);
	}

	if (contentResolution.status !== "resolved") {
		return (
			<div className="text-center py-8">
				<p style={{ color: "var(--color-text-muted)" }}>
					{contentResolution.status === "unresolvable"
						? contentResolution.reason
						: "Lesson not found"}
				</p>
				<Button variant="link" className="mt-4" onClick={() => navigate("/")}>
					Go Home
				</Button>
			</div>
		);
	}

	const handleIntroComplete = () => {
		try {
			const result = lesson.startScript(num);
			if (!result) {
				setBlockedMessage(
					"Too many apprentice items. Review your existing cards before starting new lessons.",
				);
				return;
			}
			setCards(result.cards);
			refresh();
			setPhase("quiz");
		} catch (e) {
			setBlockedMessage((e as Error).message);
		}
	};

	if (phase === "intro") {
		return (
			<div>
				<h1
					className="text-xl font-bold mb-1"
					style={{ color: "var(--color-text)" }}
				>
					Lesson {num}
				</h1>
				<p
					className="text-sm mb-6"
					style={{ color: "var(--color-text-muted)" }}
				>
					{summary.focus}
				</p>
				<LessonIntro
					summary={summary}
					content={contentResolution.content}
					onComplete={handleIntroComplete}
				/>

				<Dialog
					open={blockedMessage !== null}
					onOpenChange={(open) => {
						if (!open) {
							setBlockedMessage(null);
							navigate("/");
						}
					}}
				>
					<DialogContent>
						<DialogHeader>
							<DialogTitle>Can't start quiz yet</DialogTitle>
							<DialogDescription>{blockedMessage}</DialogDescription>
						</DialogHeader>
						<DialogFooter>
							<Button
								onClick={() => {
									setBlockedMessage(null);
									navigate("/");
								}}
							>
								Go to Reviews
							</Button>
						</DialogFooter>
					</DialogContent>
				</Dialog>
			</div>
		);
	}

	const currentLessonCard = cards[flow.cardIdx];
	if (phase === "quiz" && currentLessonCard) {
		const liveTotal = flow.correct + flow.incorrect;
		const liveAccuracy =
			liveTotal > 0 ? `${Math.round((flow.correct / liveTotal) * 100)}%` : "—";

		return (
			<div>
				{/* Session header HUD */}
				<div className="mb-4">
					<div className="flex items-center justify-between mb-2">
						<span
							className="text-sm font-semibold"
							style={{ color: "var(--color-text)" }}

