// ============================================================================
// Thai Script Learning Data
// Source: ThaiPod101 "Thai Alphabet Made Easy" Lessons 1-25
// Organized for SRS-based accelerated learning
// ============================================================================

export class LearnableItem {
	constructor(
		public readonly priority?: number,
		public readonly lesson?: number,
	) {}
}

export class ThaiSymbol extends LearnableItem {
	constructor(
		public readonly character: string,
		public readonly name: string,
		public readonly mnemonic?: string,
		public readonly audioUrl?: string,
		priority?: number,
		lesson?: number,
	) {
		super(priority, lesson);
	}
	static fromPlain({
		character,
		name,
		mnemonic,
		audioUrl,
		priority,
		lesson,
	}: {
		character: string;
		name: string;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
	}): ThaiSymbol {
		return new ThaiSymbol(
			character,
			name,
			mnemonic,
			audioUrl,
			priority,
			lesson,
		);
	}
}

export class ThaiConsonant extends ThaiSymbol {
	constructor(
		character: string,
		name: string,
		public readonly nameRomanized: string,
		public readonly nameMeaning: string,
		public readonly classType: ThaiSymbolClass,
		public readonly hasDeadEnding: boolean,
		public readonly isAspirated: boolean,
		public readonly initialSound: string,
		public readonly finalSound: string,
		mnemonic?: string,
		audioUrl?: string,
		priority?: number,
		lesson?: number,
	) {
		super(character, name, mnemonic, audioUrl, priority, lesson);
	}
	static fromPlain({
		character,
		name,
		nameRomanized,
		nameMeaning,
		classType,
		hasDeadEnding,
		isAspirated,
		initialSound,
		finalSound,
		mnemonic,
		audioUrl,
		priority,
		lesson,
	}: {
		character: string;
		name: string;
		nameRomanized: string;
		nameMeaning: string;
		classType: ThaiSymbolClass;
		hasDeadEnding: boolean;
		isAspirated: boolean;
		initialSound: string;
		finalSound: string;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
	}): ThaiConsonant {
		return new ThaiConsonant(
			character,
			name,
			nameRomanized,
			nameMeaning,
			classType,
			hasDeadEnding,
			isAspirated,
			initialSound,
			finalSound,
			mnemonic,
			audioUrl,
			priority,
			lesson,
		);
	}
}

export type VowelPosition =
	| "left"
	| "right"
	| "above"
	| "below"
	| "around"
	| "left-above"
	| "left-above-right";

export class ThaiVowel extends ThaiSymbol {
	constructor(
		character: string,
		name: string,
		public readonly length: "short" | "long",
		public readonly sound: string,
		public readonly position: VowelPosition,
		mnemonic?: string,
		audioUrl?: string,
		priority?: number,
		lesson?: number,
	) {
		super(character, name, mnemonic, audioUrl, priority, lesson);
	}
	static fromPlain({
		character,
		name,
		length,
		sound,
		position,
		mnemonic,
		audioUrl,
		priority,
		lesson,
	}: {
		character: string;
		name: string;
		length: "short" | "long";
		sound: string;
		position: VowelPosition;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
	}): ThaiVowel {
		return new ThaiVowel(
			character,
			name,
			length,
			sound,
			position,
			mnemonic,
			audioUrl,
			priority,
			lesson,
		);
	}
}

export class ThaiToneMark extends ThaiSymbol {
	constructor(
		character: string,
		name: string,
		public readonly midClassTone: ToneValue,
		public readonly highClassTone: ToneValue | null,
		public readonly lowClassTone: ToneValue | null,
		mnemonic?: string,
		audioUrl?: string,
		priority?: number,
		lesson?: number,
	) {
		super(character, name, mnemonic, audioUrl, priority, lesson);
	}
	static fromPlain({
		character,
		name,
		midClassTone,
		highClassTone,
		lowClassTone,
		mnemonic,
		audioUrl,
		priority,
		lesson,
	}: {
		character: string;
		name: string;
		midClassTone: ToneValue;
		highClassTone: ToneValue | null;
		lowClassTone: ToneValue | null;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
		lesson?: number;
	}): ThaiToneMark {
		return new ThaiToneMark(
			character,
			name,
			midClassTone,
			highClassTone,
			lowClassTone,
			mnemonic,
			audioUrl,
			priority,
			lesson,
		);
	}
}

export class ThaiWord {
	constructor(
		public readonly name: string,
		public readonly romanization: string,
		public readonly meaning: string,
		public readonly tone: ToneValue,
		public readonly toneRule: string,
		public readonly lesson: number,
		public readonly mnemonic?: string,
	) {}
	static fromPlain({
		name,
		romanization,
		meaning,
		tone,
		toneRule,
		lesson,
		mnemonic,
	}: {
		name: string;
		romanization: string;
		meaning: string;
		tone: ToneValue;
		toneRule: string;
		lesson: number;
		mnemonic?: string;
	}): ThaiWord {
		return new ThaiWord(
			name,
			romanization,
			meaning,
			tone,
			toneRule,
			lesson,
			mnemonic,
		);
	}
}

export enum ThaiSymbolClass {
	High = "high",
	Mid = "mid",
	Low = "low",
}

export type ToneValue = "mid" | "low" | "falling" | "high" | "rising";

// ============================================================================
// Tone Rules
// ============================================================================

export interface ToneRule {
