		const texts = [slide.heading, slide.prompt, ...(slide.body ?? []), ...(slide.answers ?? [])];
		for (const text of texts) {
			for (const run of text?.match(/[฀-๿]+/g) ?? []) {
				if (run.length >= 2) words.add(run);
			}
		}
	}
	return words;
